import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { inFiveMinutes, makeJWT } from "./helpers.ts";

const studentToken = (id: number, name: string): string =>
  makeJWT({ aud: "gallery|student", exp: inFiveMinutes(), sub: `${id}|${name}` });

const teacherToken = (email: string): string =>
  makeJWT({ aud: "gallery|teacher", exp: inFiveMinutes(), sub: email });

describe("StudentAuth: refresh behaviour", () => {

  afterEach(() => { vi.unstubAllGlobals(); });

  // The server keeps one refresh-token hash per student and rotates it on every refresh, so overlapping refreshes make
  // the later ones fail and fall through to "fresh-cookies", silently creating a brand-new student identity.
  it("makes only one refresh request when several callers ask for a token at once", async () => {

    let refreshCalls = 0;

    vi.stubGlobal("fetch", vi.fn((url: string) => {
      if (url.startsWith("/api/auth/student/refresh")) {
        refreshCalls += 1;
        return Promise.resolve(new Response(studentToken(42, "Ana"), { status: 200 }));
      }
      return Promise.resolve(new Response("unexpected", { status: 500 }));
    }));

    const chains = new Map<string, Promise<unknown>>();
    vi.stubGlobal("navigator", {
      locks: {
        request: (name: string, cb: () => Promise<unknown>) => {
          const prev = chains.get(name) ?? Promise.resolve();
          const run = prev.then(cb, cb);
          chains.set(name, run.catch(() => {}));
          return run;
        }
      }
    });

    vi.resetModules();
    const auth = await import("@/core/StudentAuth.ts");

    await Promise.all([auth.getAuthToken(), auth.getAuthToken(), auth.getAuthToken()]);
    expect(refreshCalls).toBe(1);

  });

  it("falls back to creating a fresh student (with the prompted name) when the refresh cookie is rejected", async () => {
    const urls: Array<string> = [];
    vi.stubGlobal("prompt", () => "Ana");
    vi.stubGlobal("fetch", vi.fn((url: string) => {
      urls.push(url);
      if (url.startsWith("/api/auth/student/refresh")) {
        return Promise.resolve(new Response("expired", { status: 401 }));
      }
      if (url.startsWith("/api/auth/student/fresh-cookies")) {
        return Promise.resolve(new Response(studentToken(7, "Ana"), { status: 200 }));
      }
      return Promise.resolve(new Response("unexpected", { status: 500 }));
    }));
    vi.resetModules();
    const auth = await import("@/core/StudentAuth.ts");

    await auth.getAuthToken();
    expect(auth.getStudentID()).toBe(7);
    expect(urls.at(-1)).toBe("/api/auth/student/fresh-cookies?username=Ana");
  });

  it("sends the refresh request with credentials so the HttpOnly cookie is included", async () => {
    vi.stubGlobal("fetch", vi.fn(() => Promise.resolve(new Response(studentToken(1, "A"), { status: 200 }))));
    vi.resetModules();
    const auth = await import("@/core/StudentAuth.ts");

    await auth.refreshAuth();
    expect(vi.mocked(fetch).mock.calls[0]![1]).toMatchObject({ method: "POST", credentials: "include" });
  });

});

describe("TeacherAuth.refreshAuth", () => {

  beforeEach(() => { vi.spyOn(console, "error").mockImplementation(() => {}); });
  afterEach(() => { vi.unstubAllGlobals(); vi.restoreAllMocks(); });

  function stubServer(refresh: Response, whoAmI: Response): void {
    vi.stubGlobal("fetch", vi.fn((url: string) =>
      Promise.resolve(url.startsWith("/api/auth/teacher/refresh") ? refresh : whoAmI)
    ));
  }

  it("stores the token and the numeric teacher ID when both requests succeed", async () => {
    stubServer(new Response(teacherToken("t@example.com"), { status: 200 }), new Response("17", { status: 200 }));
    vi.resetModules();
    const auth = await import("@/core/TeacherAuth.ts");

    await expect(auth.refreshAuth()).resolves.toBe(true);
    expect(auth.amLoggedInSimple()).toBe(true);
    expect(auth.getTeacherID()).toBe(17);
  });

  it("clears the login if the refresh request is rejected", async () => {
    stubServer(new Response("expired", { status: 403 }), new Response("", { status: 500 }));
    vi.resetModules();
    const auth = await import("@/core/TeacherAuth.ts");

    await expect(auth.refreshAuth()).resolves.toBe(false);
    expect(auth.amLoggedInSimple()).toBe(false);
  });

  it("clears the login if the server answers who-am-i with something non-numeric", async () => {
    stubServer(new Response(teacherToken("t@example.com"), { status: 200 }), new Response("oops", { status: 200 }));
    vi.resetModules();
    const auth = await import("@/core/TeacherAuth.ts");

    await expect(auth.refreshAuth()).resolves.toBe(false);
    expect(auth.amLoggedInSimple()).toBe(false);
    expect(() => auth.getTeacherID()).toThrow();
  });

});
